export function companyById(id){return CATALOG.find(c=>c.id===id);}
export function matchCompanies(q){const text=q.toLowerCase();return CATALOG.filter(c=>[c.name,c.ticker.split('.')[0],c.en.split(' · ')[0],...(/^[\u4e00-\u9fa5]{4}$/.test(c.name)?[c.name.slice(0,2)]:[]),...(c.id==='nabtesco'?['纳博特斯克']:[])].some(s=>s.length>=2&&text.includes(s.toLowerCase()))||c.id==='tsla'&&/特斯拉|optimus/i.test(text)||c.id==='hds'&&/hds/i.test(text));}
export function filterCompanies({q='',node='',market='',deep=''}={}){const term=q.trim().toLowerCase();return CATALOG.filter(c=>(!term||[c.name,c.en,c.ticker,c.description].join(' ').toLowerCase().includes(term))&&(!node||c.nodes.includes(node))&&(!market||c.market===market)&&(!deep||(deep==='deep'?c.deep:!c.deep)));}
export function filterDocuments({q='',kind='',company=''}={}){return DOCUMENTS.filter(d=>(!q||[d.title,d.publisher,d.summary,...d.companyIds.map(id=>companyById(id).name)].join(' ').toLowerCase().includes(q.toLowerCase()))&&(!kind||d.kind===kind)&&(!company||d.companyIds.includes(company))).sort((a,b)=>b.date.localeCompare(a.date));}
